#!/usr/bin/env sh
# fetch Градска управа града Београда (RS) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://data.gov.rs/s/resources/prigradski-javni-prevoz-u-u-beogradu-gtfs/20261105-115922/bgprevsuburb-belgrade-rs-1-.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
